'use strict';
function subjectProgressCards(){return `<section class="subject-progress-grid" aria-label="Tiến độ từng môn">${SUBJECTS.map(s=>{const st=subjectStats(s.id),pct=Math.round(st.seen/st.total*100);return `<article class="subject-progress-card"><div class="row"><span class="badge">${s.code}</span><b>${pct}% đã luyện</b></div><h3>${esc(s.title)}</h3><div class="progresslabel"><span>Đã trả lời</span><b>${st.seen}/${st.total}</b></div><div class="meter" role="progressbar" aria-label="Tiến độ ${esc(s.title)}" aria-valuenow="${st.seen}" aria-valuemin="0" aria-valuemax="${st.total}"><i style="width:${pct}%"></i></div><p class="micro">${st.correct} đúng gần nhất · ${st.wrong} cần ôn · ${st.saved} đánh dấu</p><button class="btn" data-course="${s.id}">${progressRoot[s.id].session?'Tiếp tục khám phá môn':'Vào góc ôn tập'} →</button></article>`;}).join('')}</section>`;}
const baseUnifiedCatalog=catalogPage;
catalogPage=function(){return baseUnifiedCatalog().replace(/<section class="academy-strip">[\s\S]*?<\/section>/,`<section class="academy-strip"><div><b>03</b><span>Môn học dùng chung động cơ</span></div><div><b>${Object.values(QUIZ_DATA).flat().filter(q=>!q.extra).length}</b><span>Câu luyện tập ở 3 môn</span></div><div><b>48</b><span>Bài tập tính toán Truyền tin</span></div><div><b>Theo nhịp bạn</b><span>Học & thi thử trên mọi thiết bị</span></div></section>`).replace('<section id="course-library"',subjectProgressCards()+'<section id="course-library"').replace('Lượt ôn Lịch sử Đảng đang chờ bạn','Lượt ôn '+esc(subjectTitle())+' đang chờ bạn').replace('Từ khóa và mốc cốt lõi được tô sáng trong bộ câu hỏi Lịch sử Đảng.','Từ khóa và mốc cốt lõi được tô sáng khi đọc câu hỏi.');};
document.addEventListener('change',e=>{if(e.target.id==='subject-switch')openSubject(e.target.value);});
